create table if not exists public.event_volunteer_roles (id uuid primary key default gen_random_uuid(),event_id uuid not null references public.school_calendar_events(id) on delete cascade,label text not null,description text not null default '',capacity integer,active boolean not null default true,created_at timestamptz not null default now());create table if not exists public.school_event_activity_links (event_id uuid not null references public.school_calendar_events(id) on delete cascade,activity_id uuid not null references public.campus_activities(id) on delete cascade,role_label text not null default 'participant',primary key(event_id,activity_id));alter table public.event_volunteer_roles enable row level security;alter table public.school_event_activity_links enable row level security;create policy event_volunteer_roles_read on public.event_volunteer_roles for select using(auth.uid() is not null);create policy event_volunteer_roles_staff on public.event_volunteer_roles for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());create policy event_activity_links_read on public.school_event_activity_links for select using(auth.uid() is not null);create policy event_activity_links_staff on public.school_event_activity_links for all using(public.school_staff_can_manage()) with check(public.school_staff_can_manage());
create or replace function public.staff_build_school_event(event_title text,event_description text,event_location text,event_starts_at timestamptz,event_ends_at timestamptz,event_category public.school_event_category,event_featured boolean,event_registration_open boolean,event_registration_capacity integer,volunteer_roles jsonb default '[]'::jsonb,activity_ids uuid[] default '{}',daily_rp_prompt text default '',publish_announcement boolean default false) returns uuid language plpgsql security definer set search_path=public as $$declare event_id uuid;role_item jsonb;activity_id uuid;begin if not public.school_staff_can_manage() then raise exception 'staff permission required'; end if;if length(trim(coalesce(event_title,'')))<3 then raise exception 'event title required'; end if;insert into public.school_calendar_events(title,description,location,starts_at,ends_at,category,status,featured,registration_open,registration_capacity,created_by) values(trim(event_title),coalesce(event_description,''),nullif(trim(coalesce(event_location,'')),''),event_starts_at,event_ends_at,event_category,'published',event_featured,event_registration_open,event_registration_capacity,auth.uid()) returning id into event_id;for role_item in select value from jsonb_array_elements(coalesce(volunteer_roles,'[]'::jsonb)) loop if nullif(trim(role_item->>'label'),'') is not null then insert into public.event_volunteer_roles(event_id,label,description,capacity) values(event_id,trim(role_item->>'label'),coalesce(role_item->>'description',''),nullif(role_item->>'capacity','')::integer); end if;end loop;foreach activity_id in array coalesce(activity_ids,'{}'::uuid[]) loop insert into public.school_event_activity_links(event_id,activity_id) values(event_id,activity_id) on conflict do nothing;end loop;if nullif(trim(daily_rp_prompt),'') is not null then insert into public.roleplay_calendar_entries(cadence,roleplay_date,title,prompt,continuity_summary,category,status,created_by,published_at) values('daily',(event_starts_at at time zone 'Asia/Tokyo')::date,event_title,trim(daily_rp_prompt),'','school_event','published',auth.uid(),now()) on conflict(cadence,roleplay_date,title) do update set prompt=excluded.prompt,status='published',published_at=now(),updated_at=now();end if;if publish_announcement then insert into public.site_announcements(title,body,category,status,featured,published_at,created_by,audience_scope,severity) values(event_title,coalesce(event_description,''),'event','published',event_featured,now(),auth.uid(),'all','normal');end if;return event_id;end;$$;revoke all on function public.staff_build_school_event(text,text,text,timestamptz,timestamptz,public.school_event_category,boolean,boolean,integer,jsonb,uuid[],text,boolean) from public;grant execute on function public.staff_build_school_event(text,text,text,timestamptz,timestamptz,public.school_event_category,boolean,boolean,integer,jsonb,uuid[],text,boolean) to authenticated;
create or replace function public.staff_approve_festival_submission(target_submission_id uuid,review_note text default '') returns uuid language plpgsql security definer set search_path=public as $$declare s public.festival_plan_submissions%rowtype;plan_id uuid;begin if not public.school_staff_can_manage() then raise exception 'staff permission required'; end if;select * into s from public.festival_plan_submissions where id=target_submission_id for update;if not found then raise exception 'submission not found'; end if;if s.status not in ('pending','draft') then raise exception 'submission already reviewed'; end if;insert into public.festival_plans(owner_type,owner_id,title,description,booth_location,attraction_type,starts_at,ends_at,status,created_by) values(s.owner_type,s.owner_id,s.title,s.description,s.booth_location,s.attraction_type,s.starts_at,s.ends_at,'approved',auth.uid()) returning id into plan_id;update public.festival_plan_submissions set status='approved',reviewer_note=coalesce(review_note,''),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=s.id;return plan_id;end;$$;revoke all on function public.staff_approve_festival_submission(uuid,text) from public;grant execute on function public.staff_approve_festival_submission(uuid,text) to authenticated;
create or replace function public.staff_award_festival_stamp(target_passport_id uuid,new_stamp_key text,new_label text) returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;begin if not public.school_staff_can_manage() then raise exception 'staff permission required'; end if;if not exists(select 1 from public.festival_passports where id=target_passport_id) then raise exception 'passport not found'; end if;if exists(select 1 from public.festival_stamps where passport_id=target_passport_id and stamp_key=new_stamp_key) then select id into new_id from public.festival_stamps where passport_id=target_passport_id and stamp_key=new_stamp_key limit 1;return new_id;end if;insert into public.festival_stamps(passport_id,stamp_key,label) values(target_passport_id,trim(new_stamp_key),trim(new_label)) returning id into new_id;return new_id;end;$$;revoke all on function public.staff_award_festival_stamp(uuid,text,text) from public;grant execute on function public.staff_award_festival_stamp(uuid,text,text) to authenticated;
